a!localVariables(


  local!intentoDescarga:if(a!isNullOrEmpty(ri!intentoDescarga),false,ri!intentoDescarga),
  {  /*Espera por BD Loading*/
    #"SYSTEM_SYSRULES_cardLayout"(
