                    document: #"_a-0000efb5-1f98-8000-9bc9-011c48011c48_609264"
                  )
                },
                isThumbnail: true,
                size: "EXTRA_SMALL"
              ),
              width: "MINIMIZE"
            ),
            #"SYSTEM_SYSRULES_sideBySideItem"(
              /* Replace this rich text with your information message */
              item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                labelPosition: "COLLAPSED",
                value: {
                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: "Descargando Archivo",
                    style: "STRONG"
                  ),
                  char(10),
                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: "El documento se está descargando en segundo plano. Estará disponible para su descarga en breve."
                  )
                },
                marginAbove: "NONE",
                marginBelow: "NONE"
              )
            ),


          },
          marginAbove: "LESS",
          marginBelow: "LESS",
          alignVertical: "TOP"
        )
      },
      marginAbove: "NONE",
      marginBelow: "LESS",
      style: "#FAF8F700",
      showBorder: false,
      padding: "LESS",
      decorativeBarPosition: "START",
      decorativeBarColor: "WARN",
      showWhen: and(
        local!intentoDescarga,
        a!isNullOrEmpty(ri!consultaDoc),
        ri!mensajeRespuesta = "Incompleto"
      )
    ),
